import { useEffect, useState } from "react";
import { ImagePlus, Star, X, ArrowUpRight } from "lucide-react";

// Replace this search URL with the cafe's Google Business Profile review URL
// (the link generated by Google Business Profile > Ask for reviews).
const GOOGLE_REVIEW_URL = "https://www.google.com/maps/search/?api=1&query=Barista+Cafe+46+Roast+Lane+Portland";

export default function RateUs() {
  const [open, setOpen] = useState(false);
  const [rating, setRating] = useState(0);
  const [message, setMessage] = useState("");
  const [image, setImage] = useState<File | null>(null);
  const [preview, setPreview] = useState("");

  useEffect(() => {
    if (!image) { setPreview(""); return; }
    const url = URL.createObjectURL(image);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [image]);

  const continueToGoogle = () => {
    if (!rating) return;
    // Google Maps does not accept review text or image data from a website URL.
    // Keep the review draft on this device so it can be copied after sign-in.
    try { localStorage.setItem("barista-review-draft", JSON.stringify({ rating, message, savedAt: new Date().toISOString() })); } catch { /* storage may be unavailable */ }
    window.open(GOOGLE_REVIEW_URL, "_blank", "noopener,noreferrer");
  };

  return <>
    <button onClick={() => setOpen(true)} className="fixed bottom-[max(1.25rem,env(safe-area-inset-bottom))] right-4 z-[120] inline-flex items-center gap-2 rounded-full bg-espresso px-4 py-3 font-display text-xs font-extrabold uppercase tracking-widest text-lemon shadow-[0_12px_35px_-8px_rgba(27,18,11,0.65)] transition hover:-translate-y-1 hover:bg-heather-deep focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-heather sm:right-6 sm:px-5 sm:py-3.5"><Star size={17} fill="currentColor"/>Rate us</button>
    {open && <div className="fixed inset-0 z-[220] flex items-end justify-center bg-cocoa/60 p-0 backdrop-blur-sm sm:items-center sm:p-5" onMouseDown={(event) => { if (event.target === event.currentTarget) setOpen(false); }}>
      <section role="dialog" aria-modal="true" aria-labelledby="rate-title" className="flex max-h-[92dvh] w-full max-w-lg flex-col overflow-hidden rounded-t-3xl bg-cream shadow-2xl sm:max-h-[90dvh] sm:rounded-3xl">
        <header className="flex shrink-0 items-center justify-between border-b border-espresso/10 px-5 py-4 sm:px-7"><div><p className="font-display text-[10px] font-extrabold uppercase tracking-[0.3em] text-heather-deep">Tell us how we did</p><h2 id="rate-title" className="mt-1 font-display text-xl font-black uppercase sm:text-2xl">Rate your visit</h2></div><button onClick={() => setOpen(false)} aria-label="Close review form" className="grid h-10 w-10 place-items-center rounded-xl hover:bg-espresso/10"><X/></button></header>
        <div className="min-h-0 space-y-5 overflow-y-auto overscroll-contain px-5 py-5 sm:px-7">
          <fieldset><legend className="text-xs font-extrabold uppercase tracking-widest">Your rating</legend><div className="mt-2 flex gap-1" role="radiogroup" aria-label="Rating"><span className="sr-only">Select a rating from one to five stars</span>{[1,2,3,4,5].map((value) => <button key={value} type="button" role="radio" aria-checked={rating === value} aria-label={`${value} star${value === 1 ? "" : "s"}`} onClick={() => setRating(value)} className="rounded-lg p-1.5 text-amber-500 transition hover:scale-110 focus-visible:outline focus-visible:outline-2 focus-visible:outline-heather"><Star size={32} fill={rating >= value ? "currentColor" : "none"}/></button>)}</div></fieldset>
          <label className="block text-xs font-extrabold uppercase tracking-widest">Your message<textarea value={message} onChange={(event) => setMessage(event.target.value)} rows={4} maxLength={1000} placeholder="Share a little about your visit…" className="mt-2 w-full resize-y rounded-2xl border border-espresso/15 bg-white px-4 py-3 text-sm font-normal normal-case tracking-normal outline-none placeholder:text-mocha/60 focus:border-heather"/><span className="mt-1 block text-right text-[10px] font-normal tracking-normal text-mocha">{message.length}/1000</span></label>
          <div><p className="text-xs font-extrabold uppercase tracking-widest">Add a photo <span className="font-normal normal-case tracking-normal text-mocha">(optional)</span></p><label className="mt-2 flex cursor-pointer items-center gap-3 rounded-2xl border border-dashed border-espresso/25 bg-white p-3 transition hover:border-heather"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-heather/15 text-heather-deep"><ImagePlus size={20}/></span><span className="min-w-0 flex-1 text-sm text-mocha">{image ? image.name : "Choose a photo from your device"}</span><input type="file" accept="image/*" onChange={(event) => setImage(event.target.files?.[0] ?? null)} className="sr-only"/></label>{preview && <div className="relative mt-3 inline-block"><img src={preview} alt="Selected photo preview" className="h-28 max-w-full rounded-xl object-cover"/><button onClick={() => setImage(null)} aria-label="Remove selected photo" className="absolute -right-2 -top-2 grid h-7 w-7 place-items-center rounded-full bg-espresso text-white"><X size={15}/></button></div>}</div>
          <div className="rounded-xl bg-heather/10 px-4 py-3 text-xs leading-relaxed text-mocha">Google requires you to sign in and post the review yourself. Your message and photo will not transfer automatically; you can copy the text and add the photo again on Google.</div>
          <button disabled={!rating} onClick={continueToGoogle} className="flex w-full items-center justify-center gap-2 rounded-xl bg-espresso px-5 py-4 font-display text-xs font-extrabold uppercase tracking-widest text-lemon transition hover:bg-heather-deep disabled:cursor-not-allowed disabled:opacity-40">Continue to Google Maps <ArrowUpRight size={16}/></button>
        </div>
      </section>
    </div>}
  </>;
}
